// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        vm.prank(0x000000000000000000000000000000000000bEEF, 0x000000000000000000000000000000000000bEEF);
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address _migrator) internal {
        vm.assume(true);
        bool reverted;
        try c.setMigrator(_migrator) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted || msg.sender == c.owner());
    }

    function testFuzz_run(address _migrator) public {
        vm.assume(uint160(_migrator) > 255 && _migrator != address(this) && _migrator != address(c) && _migrator != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _migrator != 0x000000000000000000636F6e736F6c652e6c6f67 && _migrator != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _migrator != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_migrator);
    }

    receive() external payable {}
}
